parameters.jsonBody:
={{
JSON.stringify({
  contents: [{
    role: "user",
    parts: [{
      text: (function () {
        const src = $json.output ?? $json;   // handle potential wrapper

        const prim = $json.primary_color || '';
        const sec  = $json.secondary_color || '';
        const ter  = $json.tertiary_color || '';

        const lines = [];

        // Short spec first (Gemini favors the first sentence)
        lines.push(`Shot: ${src.render_prefs?.camera || 'top-down flat lay'}; Lighting: ${src.render_prefs?.lighting || 'soft natural daylight'}; Aspect ratio: ${src.render_prefs?.aspect_ratio || '4:5'}; Style: ${src.render_prefs?.output_style || 'editorial minimalism'}.`);

        // Main scene
        lines.push((src.image_prompt || '').trim());

        // Overlays
        if (src.overlay_text?.headline) {
          lines.push(`Overlay headline: "${src.overlay_text.headline}" in ${src.overlay_text.font_style || 'bold sans-serif'}, placement: ${src.overlay_text.placement?.headline || 'bottom'}.`);
        }
        if (src.overlay_text?.watermark) {
          lines.push(`Watermark: "${src.overlay_text.watermark}", placement: ${src.overlay_text.placement?.watermark || 'bottom-right'}.`);
        }

        // Brand colors from THIS item (no cross-node lookups)
        if (prim || sec || ter) {
          lines.push(`Use brand accents: primary ${prim || ''}, secondary ${sec || ''}; background/negative space uses ${ter || ''}. Do not recolor the product or logo.`);
        }

        // Negative constraints
        if (src.negative_prompt) {
          lines.push(`AVOID: ${src.negative_prompt}`);
        }

        return lines.join(' ');
      })()
    }]
  }],
  // Optional tuning
  generationConfig: {
    temperature: 0.7,
    topP: 0.9
  }
})
}}

parameters.text:
=Create ONE concise, production-ready image prompt for an ad based on the inputs below.
Return ONLY JSON with:
{
  "image_prompt": string,        // 1 tight paragraph
  "negative_prompt": string,     // concise list-style sentence
  "overlay_text": {              // specify what to render as text overlays
    "headline": string,
    "watermark": string,
    "font_style": string,
    "placement": { "headline": "top|center|bottom|custom", "watermark": "corner|bottom-right|custom" }
  },
  "render_prefs": {
    "aspect_ratio": "1:1|4:5|3:4|16:9",
    "lighting": string,
    "camera": string,
    "depth_of_field": string,
    "output_style": string
  }
}

Inputs:
brand_name = {{ $json.brand_name }}
product = {{ $json.product }}
character = {{ $json.character }}
ad_copy = {{ $json.ad_copy }}
visual_guide = {{ $json.visual_guide }}
text_watermark = {{ $json.text_watermark }}
primary_color = {{ $json.primary_color }}
secondary_color = {{ $json.secondary_color }}
tertiary_color = {{ $json.tertiary_color }}
font_style = {{ $json.font_style }}
reference_image_summary = {{ $json.reference_image_summary }}
variant_id = {{ $json.variant_id }}
variation_guidance = {{ $json.variation_guidance }}
render_prefs_override = {{ $json.render_prefs_override }}
seed = {{ $json.seed }}
ad_copy_hint = {{ $json.ad_copy_hint }}

Hard constraints:
- Align composition to visual_guide, reference_image_summary, and variation_guidance.
- If render_prefs_override.camera or .lighting is present, prefer those over defaults.
- Keep brand label legible; product is the hero.
- Use primary_color and secondary_color as subtle prop/accent tones; reserve tertiary_color for background or negative space.
- Include ad_copy as headline overlay and text_watermark in a corner.
- Mention camera angle and lighting explicitly in image_prompt.
- Avoid clutter, harsh reflections, color cast, warped labels, extra logos, or hands covering the logo.
- Product-only scene: exclude all human elements — no people, faces, hands, skin, hair, or body parts.
- If any input suggests a character, IGNORE it; do not include human figures or hints of them.

Defaults if unspecified:
- aspect_ratio = "4:5"
- lighting = "soft natural daylight"
- camera = "top-down flat lay" if visual_guide suggests overhead, else "three-quarter product angle"
- depth_of_field = "deep, product fully sharp"
- output_style = "editorial minimalism"

Return ONLY the JSON. No markdown, no explanations.

parameters.jsCode:
// 1) Read JSON string from Vision
const raw = $('Vision').first().json?.choices?.[0]?.message?.content ?? '{}';

// 2) Parse (strip accidental code fences just in case)
const cleaned = raw
  .replace(/^\s*```(?:json)?/i, '')
  .replace(/```?\s*$/, '')
  .trim();

let v = {};
try { v = JSON.parse(cleaned); } catch (e) { v = {}; }

// 3) Helpers
const isHex = s => typeof s === 'string' && /^#?[0-9a-fA-F]{6}$/.test(s);
const normHex = s => s?.startsWith('#') ? s : (s ? '#'+s : s);
const isNeutral = s => /white|black|gray|grey|charcoal|ivory|off[-\s]?white/i.test(s || '');

// 4) Normalize palette -> [{hex,name}] and order (non-neutral first)
let palette = Array.isArray(v.palette) ? v.palette : [];
palette = palette
  .map(c => ({ hex: normHex(c?.hex), name: (c?.name || '').trim() }))
  .filter(c => isHex(c.hex));

const nonNeutral = palette.filter(c => !isNeutral(c.name) && !isNeutral(c.hex));
const neutral    = palette.filter(c =>  isNeutral(c.name) ||  isNeutral(c.hex));
const ordered    = [...nonNeutral, ...neutral];

// 5) Choose primary/secondary/tertiary with safe fallbacks
const primary   = ordered[0] || { hex: '#d89c94', name: 'Rosewood' };
const secondary = ordered[1] || { hex: '#f2e9e1', name: 'Pale Ivory' };
const tertiary  = ordered[2] || neutral[0] || { hex: '#ffffff', name: 'White' };

// 6) Flatten core fields with defaults
const out = {
  brand_name: v.brand_name || 'Unknown Brand',
  product: v.product || 'Unknown Product',
  character: v.character || 'Minimalist beauty muse',
  ad_copy: v.ad_copy || 'Glow your own way',
  visual_guide: v.visual_guide || 'Top-down, soft daylight, neutral backdrop, minimal editorial styling.',
  text_watermark: (v.text_watermark && !/^none|null$/i.test(v.text_watermark)) ? v.text_watermark : (v.brand_name || 'Brand'),
  font_style: v.font_style || 'Bold sans-serif',
  reference_image_summary: v.reference_image_summary || 'Product image on neutral background.',
  palette_full: palette,
  primary_color: primary.hex,
  secondary_color: secondary.hex,
  tertiary_color: tertiary.hex
};

// 7) Emit single item
return [out];

const base = $json;
let n = parseInt($('On form submission').first().json['# of Images'] ?? 1, 10);
if (!Number.isFinite(n)) n = 1;
n = Math.min(Math.max(n, 1), 10);

const angles = [
  'top-down flat lay',
  'three-quarter product angle (30°)',
  'angled overhead (15° tilt)',
  'eye-level hero shot'
];
const lightings = [
  'soft natural daylight',
  'bright, even daylight',
  'diffused window light',
  'soft studio light with diffuser'
];

const headlineSeeds = [
  'instant radiance', 'effortless glow', 'fresh finish',
  'skin-first beauty', 'everyday dewy', 'soft-focus sheen',
  'natural luminosity', 'quiet luxury glow', 'no-makeup look',
  'your-skin boost'
];

const out = [];
for (let i = 0; i < n; i++) {
  const angle = angles[i % angles.length];
  const lighting = lightings[i % lightings.length];
  const seed = headlineSeeds[i % headlineSeeds.length];

  out.push({
    ...base,
    // hard-remove any prior character suggestion
    character: null,
    variant_id: i + 1,
    ad_copy: null,
    ad_copy_hint: `Create a short headline inspired by: ${seed}. 2–5 words, brand-safe.`,
    variation_guidance: `Product-only composition. Use ${angle}; lighting ${lighting}. Keep label fully legible; do not recolor the product.`,
    render_prefs_override: { camera: angle, lighting },
    seed: Math.floor(Math.random() * 1e9)
  });
}
return out;

// Unwrap agent output
const out = $json.output ?? $json;

// Pull the per-variant fields directly from THIS item if they exist;
// if they were dropped earlier, fall back to sensible defaults.
const primary   = $json.primary_color   ?? '#f4e8e4';
const secondary = $json.secondary_color ?? '#d7a79e';
const tertiary  = $json.tertiary_color  ?? '#ffffff';
const variantId = $json.variant_id      ?? ($json.variant_id === 0 ? 0 : null);

// Merge overrides into render_prefs
const rp = out.render_prefs || {};
const ov = $json.render_prefs_override || {};
const render_prefs = {
  aspect_ratio: rp.aspect_ratio || '4:5',
  lighting: ov.lighting || rp.lighting || 'soft natural daylight',
  camera: ov.camera || rp.camera || 'top-down flat lay',
  depth_of_field: rp.depth_of_field || 'deep, product fully sharp',
  output_style: rp.output_style || 'editorial minimalism',
};

// Return a SINGLE object
return {
  ...out,
  render_prefs,
  primary_color: primary,
  secondary_color: secondary,
  tertiary_color: tertiary,
  variant_id: variantId
};
